import { kanaToRomajiFull } from '@/lib/utils/romaji';
import type { SymptomHistoryPrompt } from '../schema';

type PhraseRow = [japanese: string, kana: string, indonesian: string, english: string];
type PromptRow = {
  focusId: string;
  focusEn: string;
  reasonId: string;
  reasonEn: string;
  ask: PhraseRow;
  answers?: PhraseRow[];
};

const line = ([japanese, kana, indonesian, english]: PhraseRow) => ({
  japanese,
  kana,
  romaji: kanaToRomajiFull(kana),
  indonesian,
  english,
});

function prompts(rows: PromptRow[]): SymptomHistoryPrompt[] {
  return rows.map((row, index) => ({
    id: `hpi-${index + 1}`,
    focusIndonesian: row.focusId,
    focusEnglish: row.focusEn,
    clinicalReasonIndonesian: row.reasonId,
    clinicalReasonEnglish: row.reasonEn,
    question: line(row.ask),
    patientAnswers: (row.answers ?? []).map(line),
  }));
}

